examples.template:
HStack(spacing: 0) {
    VStack(alignment: .leading, spacing: 0) {
        ForEach(items, id: \.self) { item in
            Button { selection = item } label: {
                Text(item).monarchTextStyle(.bodySmall)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(theme.spacing.space3)
                    .background(selection == item ? theme.colors.accentSubtle : Color.clear)
            }
            .buttonStyle(.plain)
            .accessibilityAddTraits(selection == item ? .isSelected : [])
        }
        Spacer(minLength: 0)
    }
    .frame(width: theme.spacing.space24 * 2)
    Rectangle().fill(theme.colors.borderSubtle).frame(width: 1)
    Group {
        if let selection {
            Text(selection).monarchTextStyle(.bodySmall)
        } else {
            VStack(spacing: theme.spacing.space2) {
                Text({{empty.title}}).monarchTextStyle(.bodyStrong)
                Text({{empty.description}}).monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
            }
            .multilineTextAlignment(.center)
        }
    }
    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
    .padding(.top, theme.spacing.space8)
}
.frame(height: theme.spacing.space24 * 3)

